insert into public.book_highlights (book_id, section_order, display_order, word, type, context, ai_definition, explanation) values
('20000005-0000-4000-8000-000000000005'::uuid, 1, 1, 'geldiniz', 'Anahtar Kavram', 'GİRİŞ Hoş geldiniz.', 'geldiniz, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde geldiniz, su baglam icinde anlam kazanir: "GİRİŞ Hoş geldiniz."'),
('20000005-0000-4000-8000-000000000005'::uuid, 2, 2, 'çünkü dünyamızda cömertçe', 'Anahtar Kavram', 'bir durumdur bu, çünkü dünyamızda cömertçe ve uysalca bir araya gelip canlı varlıklar oluşturan atomlar, bunu uzayın başka bir yerinde yapmaktan geri duran atomların tıpatıp ayn...', 'çünkü dünyamızda cömertçe, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde çünkü dünyamızda cömertçe, su baglam icinde anlam kazanir: "bir durumdur bu, çünkü dünyamızda cömertçe ve uysalca bir araya gelip canlı varlıklar oluşturan atomlar, bunu uzayın başka bir yerinde yapmaktan geri duran atomların tıpatıp ayn..."'),
('20000005-0000-4000-8000-000000000005'::uuid, 3, 3, 'olmuş milyarlarca canlı', 'Anahtar Kavram', 'olmuş milyarlarca canlı varlık türünün çoğu (iddialara göre, yüzde 99,99’u) artık ırtadan kalkmıştır.', 'olmuş milyarlarca canlı, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde olmuş milyarlarca canlı, su baglam icinde anlam kazanir: "olmuş milyarlarca canlı varlık türünün çoğu (iddialara göre, yüzde 99,99’u) artık ırtadan kalkmıştır."'),
('20000005-0000-4000-8000-000000000005'::uuid, 4, 4, 'sağlıklı olmuşlar kader', 'Anahtar Kavram', 'bulabilecek kadar cazip, üreyebilecek kadar sağlıklı olmuşlar, kader ve koşullar tarafından yeterince kollanmışlar ve dolayısıyla bütün bunları yapabilecek kadar uzun yaşamışlar.', 'sağlıklı olmuşlar kader, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde sağlıklı olmuşlar kader, su baglam icinde anlam kazanir: "bulabilecek kadar cazip, üreyebilecek kadar sağlıklı olmuşlar, kader ve koşullar tarafından yeterince kollanmışlar ve dolayısıyla bütün bunları yapabilecek kadar uzun yaşamışlar."'),
('20000005-0000-4000-8000-000000000005'::uuid, 5, 5, 'Kuzey Kutbu arasında', 'Anahtar Kavram', 'Amerika ile Kuzey Kutbu arasında uzanan 6.400 kilometre derinliğindeki bir uçurumun kıyısından aşağıya uçtuğunu canlandırmıştım gözümde.', 'Kuzey Kutbu arasında, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde Kuzey Kutbu arasında, su baglam icinde anlam kazanir: "Amerika ile Kuzey Kutbu arasında uzanan 6.400 kilometre derinliğindeki bir uçurumun kıyısından aşağıya uçtuğunu canlandırmıştım gözümde."'),
('20000005-0000-4000-8000-000000000005'::uuid, 6, 6, 'türden ayrıntılar konusunda', 'Anahtar Kavram', 'Ama kitabın yazarı bu türden ayrıntılar konusunda tuhaf bir suskunluk sergiliyordu.', 'türden ayrıntılar konusunda, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde türden ayrıntılar konusunda, su baglam icinde anlam kazanir: "Ama kitabın yazarı bu türden ayrıntılar konusunda tuhaf bir suskunluk sergiliyordu."'),
('20000005-0000-4000-8000-000000000005'::uuid, 7, 7, 'okyanusların tuzluluk derecesinin', 'Anahtar Kavram', 'okyanusların tuzluluk derecesinin beni ilgilendirmesi gereken bir konu olup olmadığını bilmiyordum.', 'okyanusların tuzluluk derecesinin, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde okyanusların tuzluluk derecesinin, su baglam icinde anlam kazanir: "okyanusların tuzluluk derecesinin beni ilgilendirmesi gereken bir konu olup olmadığını bilmiyordum."'),
('20000005-0000-4000-8000-000000000005'::uuid, 9, 8, 'düzlemdedir', 'Anahtar Kavram', 'Hepsi aynı düzlemdedir.', 'düzlemdedir, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde düzlemdedir, su baglam icinde anlam kazanir: "Hepsi aynı düzlemdedir."'),
('20000005-0000-4000-8000-000000000005'::uuid, 10, 9, 'iddiasız olduğunu idrak', 'Anahtar Kavram', 'Ne kadar uğraşırsanız uğraşın, bir protonun ne denli ufak, hacimsel açıdan ne iddiasız olduğunu idrak etmeyi asla başaramazsınız.', 'iddiasız olduğunu idrak, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde iddiasız olduğunu idrak, su baglam icinde anlam kazanir: "Ne kadar uğraşırsanız uğraşın, bir protonun ne denli ufak, hacimsel açıdan ne iddiasız olduğunu idrak etmeyi asla başaramazsınız."'),
('20000005-0000-4000-8000-000000000005'::uuid, 11, 10, 'orada durup sessizce', 'Anahtar Kavram', 'süre önce, parlak bir fikir gibi aniden peyda mı olduğunu, ya da ezelden beri orada durup, sessizce doğru anı mı beklediğini bile soramayız.', 'orada durup sessizce, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde orada durup sessizce, su baglam icinde anlam kazanir: "süre önce, parlak bir fikir gibi aniden peyda mı olduğunu, ya da ezelden beri orada durup, sessizce doğru anı mı beklediğini bile soramayız."'),
('20000005-0000-4000-8000-000000000005'::uuid, 12, 11, 'aslında yanlış bilmiş', 'Anahtar Kavram', 'çoğunu da aslında yanlış bilmiş ya da uzunca bir süre bildiğimizi sanmışız.', 'aslında yanlış bilmiş, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde aslında yanlış bilmiş, su baglam icinde anlam kazanir: "çoğunu da aslında yanlış bilmiş ya da uzunca bir süre bildiğimizi sanmışız."'),
('20000005-0000-4000-8000-000000000005'::uuid, 13, 12, 'Wilson’ın işitmekte oldukları', 'Anahtar Kavram', 'Penzias ile Wilson’ın işitmekte oldukları ses, elbette Gamow’un öngördüğü sesti.', 'Wilson’ın işitmekte oldukları, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde Wilson’ın işitmekte oldukları, su baglam icinde anlam kazanir: "Penzias ile Wilson’ın işitmekte oldukları ses, elbette Gamow’un öngördüğü sesti."'),
('20000005-0000-4000-8000-000000000005'::uuid, 14, 13, 'herkesçe yaşanan', 'Anahtar Kavram', 'herkesçe yaşanan bir deneyimdir.', 'herkesçe yaşanan, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde herkesçe yaşanan, su baglam icinde anlam kazanir: "herkesçe yaşanan bir deneyimdir."'),
('20000005-0000-4000-8000-000000000005'::uuid, 15, 14, 'inanırlar', 'Anahtar Kavram', 'inanırlar.', 'inanırlar, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde inanırlar, su baglam icinde anlam kazanir: "inanırlar."'),
