insert into public.book_highlights (book_id, section_order, display_order, word, type, context, ai_definition, explanation) values
('20000006-0000-4000-8000-000000000006'::uuid, 33, 31, 'sözleri güzelce süslenmiş', 'Anahtar Kavram', 'yeminleri ve sözleri güzelce süslenmiş bir kağıda yazdığında ve dokümanın altına kendi şatafatlı imzasını attığında, hokus pokus, yeni bir şirket kurulmuş olur.', 'sözleri güzelce süslenmiş, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde sözleri güzelce süslenmiş, su baglam icinde anlam kazanir: "yeminleri ve sözleri güzelce süslenmiş bir kağıda yazdığında ve dokümanın altına kendi şatafatlı imzasını attığında, hokus pokus, yeni bir şirket kurulmuş olur."'),
('20000006-0000-4000-8000-000000000006'::uuid, 34, 32, 'sahiptir', 'Anahtar Kavram', 'sahiptir.', 'sahiptir, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde sahiptir, su baglam icinde anlam kazanir: "sahiptir."'),
('20000006-0000-4000-8000-000000000006'::uuid, 35, 33, 'zamanda çevresel etkenler', 'Anahtar Kavram', 'zamanda çevresel etkenler ve bireysel tuhaflıklar tarafından da şekillendirilir.', 'zamanda çevresel etkenler, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde zamanda çevresel etkenler, su baglam icinde anlam kazanir: "zamanda çevresel etkenler ve bireysel tuhaflıklar tarafından da şekillendirilir."'),
('20000006-0000-4000-8000-000000000006'::uuid, 36, 34, 'sürülerinin gençlerinin önemli', 'Anahtar Kavram', 'kullanıp, kendi sürülerinin gençlerinin önemli bir kısmına babalık ederken, Katolik alfa erkeği cinsel birleşmeden ve çocuk bakımından tamamen kaçınır.', 'sürülerinin gençlerinin önemli, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde sürülerinin gençlerinin önemli, su baglam icinde anlam kazanir: "kullanıp, kendi sürülerinin gençlerinin önemli bir kısmına babalık ederken, Katolik alfa erkeği cinsel birleşmeden ve çocuk bakımından tamamen kaçınır."'),
('20000006-0000-4000-8000-000000000006'::uuid, 37, 35, 'Yvette Taborin Shells', 'Anahtar Kavram', '6- Yvette Taborin, “Shells of the French Aurignacian and Perigordian”, Before Lascaux: The Complete Record of the Early Upper Paleolithic, Heidi Knecht, Anne Pike-Tay ve Randall...', 'Yvette Taborin Shells, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde Yvette Taborin Shells, su baglam icinde anlam kazanir: "6- Yvette Taborin, “Shells of the French Aurignacian and Perigordian”, Before Lascaux: The Complete Record of the Early Upper Paleolithic, Heidi Knecht, Anne Pike-Tay ve Randall..."'),
('20000006-0000-4000-8000-000000000006'::uuid, 38, 36, 'bütün sürünün etrafını', 'Anahtar Kavram', 'biri de, bütün sürünün etrafını çevirip onları dar bir boğaza doğru sürerek topluca öldürülmelerini kolaylaştırmaktı.', 'bütün sürünün etrafını, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde bütün sürünün etrafını, su baglam icinde anlam kazanir: "biri de, bütün sürünün etrafını çevirip onları dar bir boğaza doğru sürerek topluca öldürülmelerini kolaylaştırmaktı."'),
('20000006-0000-4000-8000-000000000006'::uuid, 39, 37, 'ettiği hayali gerçekliklerin', 'Anahtar Kavram', 'Sapiens’in icat ettiği hayali gerçekliklerin muazzam çeşitliliği ve bunun sonucu olarak gelişen davranış örüntülerinin çokluğu, “kültür” dediğimiz şeyin başlıca bileşenleridir.', 'ettiği hayali gerçekliklerin, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde ettiği hayali gerçekliklerin, su baglam icinde anlam kazanir: "Sapiens’in icat ettiği hayali gerçekliklerin muazzam çeşitliliği ve bunun sonucu olarak gelişen davranış örüntülerinin çokluğu, “kültür” dediğimiz şeyin başlıca bileşenleridir."'),
('20000006-0000-4000-8000-000000000006'::uuid, 40, 38, 'arada tutan efsanevi', 'Anahtar Kavram', 'arada tutan efsanevi bir yapıştırıcıdır.', 'arada tutan efsanevi, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde arada tutan efsanevi, su baglam icinde anlam kazanir: "arada tutan efsanevi bir yapıştırıcıdır."'),
('20000006-0000-4000-8000-000000000006'::uuid, 41, 39, 'entelektüel becerilere sahipti', 'Anahtar Kavram', 'aynı fiziksel, duygusal ve entelektüel becerilere sahipti.', 'entelektüel becerilere sahipti, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde entelektüel becerilere sahipti, su baglam icinde anlam kazanir: "aynı fiziksel, duygusal ve entelektüel becerilere sahipti."'),
('20000006-0000-4000-8000-000000000006'::uuid, 42, 40, 'tatlılar nadiren bulunurdu', 'Anahtar Kavram', 'tatlılar nadiren bulunurdu ve gıda da çok bol sayılmazdı.', 'tatlılar nadiren bulunurdu, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde tatlılar nadiren bulunurdu, su baglam icinde anlam kazanir: "tatlılar nadiren bulunurdu ve gıda da çok bol sayılmazdı."'),
('20000006-0000-4000-8000-000000000006'::uuid, 43, 41, 'kazanacaktır', 'Anahtar Kavram', 'kazanacaktır.', 'kazanacaktır, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde kazanacaktır, su baglam icinde anlam kazanir: "kazanacaktır."'),
('20000006-0000-4000-8000-000000000006'::uuid, 44, 42, 'arkeolojik durumdan kaynaklanır', 'Anahtar Kavram', 'yanlış anlaşılma da bu arkeolojik durumdan kaynaklanır.', 'arkeolojik durumdan kaynaklanır, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde arkeolojik durumdan kaynaklanır, su baglam icinde anlam kazanir: "yanlış anlaşılma da bu arkeolojik durumdan kaynaklanır."'),
('20000006-0000-4000-8000-000000000006'::uuid, 45, 43, 'neleri varsa sırtlarındaki', 'Anahtar Kavram', 'bazen her gün taşınırlardı ve bu sırada da neleri varsa sırtlarındaki bohçaya atarlardı.', 'neleri varsa sırtlarındaki, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde neleri varsa sırtlarındaki, su baglam icinde anlam kazanir: "bazen her gün taşınırlardı ve bu sırada da neleri varsa sırtlarındaki bohçaya atarlardı."'),
('20000006-0000-4000-8000-000000000006'::uuid, 46, 44, 'önemli özelliği birbirlerinden', 'Anahtar Kavram', 'Üçüncüsü, avcı toplayıcı toplulukların en önemli özelliği birbirlerinden nasıl ayrıldıklarıdır.', 'önemli özelliği birbirlerinden, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde önemli özelliği birbirlerinden, su baglam icinde anlam kazanir: "Üçüncüsü, avcı toplayıcı toplulukların en önemli özelliği birbirlerinden nasıl ayrıldıklarıdır."'),
('20000006-0000-4000-8000-000000000006'::uuid, 47, 45, 'gruptan farklı', 'Anahtar Kavram', 'bir gruptan farklı bir dil konuştuğuna inanmak için pek çok sebep vardır.', 'gruptan farklı, bu bolumde one cikan baglamsal bir kavram veya ifadedir.', 'Bu bolumde gruptan farklı, su baglam icinde anlam kazanir: "bir gruptan farklı bir dil konuştuğuna inanmak için pek çok sebep vardır."'),
